1	"use client";
2	
3	import { useState } from "react";
4	import {
5	  AlertCircle,
6	  ArrowLeft,
7	  Check,
8	  ClipboardCopy,
9	  Clock3,
10	  ExternalLink,
11	  GitPullRequest,
12	  Layers,
13	  RefreshCw,
14	} from "lucide-react";
15	import { useWorkspaceContext } from "@/features/workspaces/context/WorkspaceContext";
16	import { useFeatureDetail, useFeatureTask } from "../../hooks/useFeatureDetail";
17	import { formatTimestamp } from "@/lib/time";
18	import {
19	  getFeatureStatusColor,
20	  getFeatureStatusLabel,
21	} from "../../lib/status";
22	import {
23	  formatStatusLabel,
24	  getStatusStyle,
25	} from "@/features/tasks/lib/status";
26	import type { FeatureDetail, TaskSummary, TaskDetail } from "@/services/workflow-backend/types";
27	
28	export type FeatureTabViewProps = {
29	  workspaceId: string;
30	  featureId: string;
31	};
32	
33	type FeatureTabPanel = "tasks" | "product_spec" | "technical_design";
34	
35	export function FeatureTabView({ workspaceId, featureId }: FeatureTabViewProps) {
36	  const { feature, loading, error, reload } = useFeatureDetail(workspaceId, featureId);
37	
38	  if (loading) {
39	    return (
40	      <div
41	        data-feature-tab-loading
42	        className="flex flex-1 items-center justify-center"
43	      >
44	        <p className="text-sm text-text-muted">Loading feature…</p>
45	      </div>
46	    );
47	  }
48	
49	  if (error) {
50	    return (
51	      <div
52	        data-feature-tab-error
53	        className="flex flex-1 flex-col items-center justify-center gap-4"
54	      >
55	        <AlertCircle className="h-8 w-8 text-danger" aria-hidden="true" />
56	        <p className="text-sm text-text-secondary">
57	          {error.message || "Failed to load feature."}
58	        </p>
59	        {error.retryable && (
60	          <button
61	            type="button"
62	            onClick={reload}
63	            className="flex items-center gap-2 border border-border bg-surface px-3 py-1.5 text-xs font-medium text-text-primary transition-colors hover:bg-surface-subtle"
64	          >
65	            <RefreshCw className="h-3.5 w-3.5" aria-hidden="true" />
66	            Retry
67	          </button>
68	        )}
69	      </div>
70	    );
71	  }
72	
73	  if (!feature) return null;
74	
75	  return <FeatureTabContent feature={feature} onReload={reload} />;
76	}
77	
78	function FeatureTabContent({
79	  feature,
80	  onReload,
81	}: {
82	  feature: FeatureDetail;
83	  onReload: () => void;
84	}) {
85	  const { goToBoard } = useWorkspaceContext();
86	  const [copied, setCopied] = useState(false);
87	  const [activePanel, setActivePanel] = useState<FeatureTabPanel>("tasks");
88	  const [drilldownTaskId, setDrilldownTaskId] = useState<string | null>(null);
89	
90	  function handleCopyId() {
91	    const textToCopy = feature.feature_name || feature.feature_id || feature.id;
92	    if (navigator.clipboard) {
93	      navigator.clipboard.writeText(textToCopy).then(() => {
94	        setCopied(true);
95	        setTimeout(() => setCopied(false), 1500);
96	      });
97	    } else {
98	      const el = document.createElement("textarea");
99	      el.value = textToCopy;
100	      document.body.appendChild(el);
101	      el.select();
102	      document.execCommand("copy");
103	      document.body.removeChild(el);
104	      setCopied(true);
105	      setTimeout(() => setCopied(false), 1500);
106	    }
107	  }
108	
109	  const statusColor = getFeatureStatusColor(feature.status);
110	  const statusLabel = getFeatureStatusLabel(feature.status);
111	
112	  if (drilldownTaskId) {
113	    return (
114	      <FeatureTaskDrilldown
115	        workspaceId={feature.workspace_id}
116	        featureId={feature.id}
117	        taskId={drilldownTaskId}
118	        onBack={() => setDrilldownTaskId(null)}
119	      />
120	    );
121	  }
122	
123	  return (
124	    <div
125	      data-feature-tab-content
126	      className="flex h-full flex-col overflow-hidden"
127	    >
128	      {/* Feature tab header */}
129	      <header
130	        data-feature-tab-header
131	        className="flex shrink-0 items-center gap-3 border-b border-border bg-surface px-6 py-4"
132	      >
133	        <button
134	          type="button"
135	          data-back-to-board
136	          onClick={goToBoard}
137	          aria-label="Back to board"
138	          className="flex items-center gap-1.5 text-xs text-text-secondary transition-colors hover:text-text-primary"
139	        >
140	          <ArrowLeft className="h-3.5 w-3.5" aria-hidden="true" />
141	          Board
142	        </button>
143	        <span className="h-4 w-px bg-border" aria-hidden="true" />
144	
145	        <div className="flex min-w-0 flex-1 flex-wrap items-center gap-2">
146	          {/* Copy feature id button */}
147	          <button
148	            type="button"
149	            data-copy-feature-id
150	            onClick={handleCopyId}
151	            aria-label={`Copy feature id ${feature.feature_name}`}
152	            title="Copy feature ID"
153	            className="flex items-center gap-1 bg-chip-bg px-2 py-0.5 text-xs font-semibold uppercase tracking-wide text-text-secondary transition-colors hover:bg-primary-light hover:text-primary"
154	          >
155	            {feature.feature_name || feature.feature_id}
156	            {copied ? (
157	              <Check className="h-3 w-3 text-success" aria-hidden="true" />
158	            ) : (
159	              <ClipboardCopy className="h-3 w-3" aria-hidden="true" />
160	            )}
161	          </button>
162	
163	          {/* Status badge */}
164	          <span
165	            data-feature-status={feature.status}
166	            className="inline-flex items-center gap-1.5 px-2 py-0.5 text-xs font-semibold uppercase tracking-wide"
167	            style={{ backgroundColor: statusColor + "22", color: statusColor }}
168	          >
169	            <span
170	              className="h-1.5 w-1.5 rounded-full"
171	              style={{ backgroundColor: statusColor }}
172	              aria-hidden="true"
173	            />
174	            {statusLabel}
175	          </span>
176	
177	          {/* Stage badge */}
178	          {feature.current_stage && (
179	            <span
180	              data-feature-stage
181	              className="flex items-center gap-1 bg-surface-secondary px-2 py-0.5 text-xs font-medium text-text-secondary"
182	            >
183	              <Layers className="h-3 w-3 shrink-0" aria-hidden="true" />
184	              {feature.current_stage}
185	            </span>
186	          )}
187	
188	          <h1 className="min-w-0 truncate text-base font-semibold text-text-primary">
189	            {feature.title || feature.feature_name}
190	          </h1>
191	        </div>
192	
193	        {/* Updated time */}
194	        {feature.updated_at && (
195	          <span
196	            data-feature-updated-at={feature.updated_at}
197	            className="shrink-0 flex items-center gap-1 text-xs text-text-muted"
198	          >
199	            <Clock3 className="h-3.5 w-3.5" aria-hidden="true" />
200	            {formatTimestamp(feature.updated_at)}
201	          </span>
202	        )}
203	
204	        {/* Task counts */}
205	        {feature.task_counts && (
206	          <FeatureTaskCountsBadge counts={feature.task_counts} />
207	        )}
208	
209	        <button
210	          type="button"
211	          onClick={onReload}
212	          aria-label="Reload feature"
213	          className="shrink-0 p-1 text-text-secondary transition-colors hover:text-text-primary"
214	        >
215	          <RefreshCw className="h-4 w-4" aria-hidden="true" />
216	        </button>
217	      </header>
218	
219	      {/* Source state stale warning */}
220	      {feature.source_state?.stale && (
221	        <div className="flex shrink-0 items-center gap-2 border-b border-border bg-warning-bg px-6 py-2 text-xs text-warning">
222	          <AlertCircle className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
223	          <span>
224	            Data may be stale
225	            {feature.source_state.error_code
226	              ? ` (${feature.source_state.error_code})`
227	              : ""}
228	          </span>
229	        </div>
230	      )}
231	
232	      {/* Panel navigation */}
233	      <div className="flex shrink-0 gap-0 border-b border-border bg-surface">
234	        <PanelTab
235	          label="Tasks"
236	          active={activePanel === "tasks"}
237	          onClick={() => setActivePanel("tasks")}
238	          dataAttr="data-panel-tasks"
239	        />
240	        <PanelTab
241	          label="Product Spec"
242	          active={activePanel === "product_spec"}
243	          onClick={() => setActivePanel("product_spec")}
244	          dataAttr="data-panel-product-spec"
245	        />
246	        <PanelTab
247	          label="Technical Design"
248	          active={activePanel === "technical_design"}
249	          onClick={() => setActivePanel("technical_design")}
250	          dataAttr="data-panel-technical-design"
251	        />
252	      </div>
253	
254	      {/* Panel content */}
255	      <div className="flex-1 overflow-y-auto">
256	        {activePanel === "tasks" && (
257	          <FeatureTasksPanel
258	            feature={feature}
259	            onDrilldown={setDrilldownTaskId}
260	          />
261	        )}
262	        {activePanel === "product_spec" && (
263	          <FeatureDocumentPanel
264	            feature={feature}
265	            documentType="product_spec"
266	          />
267	        )}
268	        {activePanel === "technical_design" && (
269	          <FeatureDocumentPanel
270	            feature={feature}
271	            documentType="technical_design"
272	          />
273	        )}
274	      </div>
275	    </div>
276	  );
277	}
278	
279	function PanelTab({
280	  label,
281	  active,
282	  onClick,
283	  dataAttr,
284	}: {
285	  label: string;
286	  active: boolean;
287	  onClick: () => void;
288	  dataAttr: string;
289	}) {
290	  const attrs: Record<string, string> = { [dataAttr]: "" };
291	  return (
292	    <button
293	      type="button"
294	      role="tab"
295	      aria-selected={active}
296	      onClick={onClick}
297	      {...attrs}
298	      className={
299	        "px-5 py-2.5 text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-primary " +
300	        (active
301	          ? "border-b-2 border-b-success text-text-primary"
302	          : "text-text-secondary hover:bg-surface-subtle hover:text-text-primary")
303	      }
304	    >
305	      {label}
306	    </button>
307	  );
308	}
309	
310	function FeatureTaskCountsBadge({
311	  counts,
312	}: {
313	  counts: FeatureDetail["task_counts"];
314	}) {
315	  return (
316	    <span
317	      data-feature-task-counts
318	      className="flex shrink-0 items-center gap-1.5 text-xs text-text-muted"
319	      title={`Total: ${counts.total}, Done: ${counts.done}, In progress: ${counts.in_progress}, Blocked: ${counts.blocked}`}
320	    >
321	      <span className="text-text-secondary font-medium">{counts.done}</span>
322	      <span>/</span>
323	      <span>{counts.total}</span>
324	      <span className="hidden sm:inline">tasks done</span>
325	    </span>
326	  );
327	}
328	
329	function FeatureTasksPanel({
330	  feature,
331	  onDrilldown,
332	}: {
333	  feature: FeatureDetail;
334	  onDrilldown: (taskId: string) => void;
335	}) {
336	  const tasks = feature.tasks ?? [];
337	
338	  if (tasks.length === 0) {
339	    return (
340	      <div
341	        data-feature-tasks-empty
342	        className="flex flex-1 flex-col items-center justify-center gap-2 py-20"
343	      >
344	        <p className="text-sm text-text-muted">No tasks in this feature.</p>
345	      </div>
346	    );
347	  }
348	
349	  return (
350	    <div
351	      data-feature-tasks-list
352	      className="mx-auto max-w-3xl px-6 py-6 space-y-2"
353	    >
354	      {tasks.map((task) => (
355	        <FeatureTaskRow
356	          key={task.id}
357	          task={task}
358	          onDrilldown={() => onDrilldown(task.id)}
359	        />
360	      ))}
361	    </div>
362	  );
363	}
364	
365	function FeatureTaskRow({
366	  task,
367	  onDrilldown,
368	}: {
369	  task: TaskSummary;
370	  onDrilldown: () => void;
371	}) {
372	  const statusStyle = getStatusStyle(task.status);
373	
374	  return (
375	    <button
376	      type="button"
377	      data-feature-task-row={task.task_name}
378	      onClick={onDrilldown}
379	      aria-label={`Open task ${task.task_name}`}
380	      className="flex w-full min-w-0 items-center gap-3 border border-border bg-surface px-4 py-3 text-left transition-colors hover:border-primary-light hover:bg-surface-subtle focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
381	    >
382	      <span className="shrink-0 bg-chip-bg px-2 py-0.5 font-mono text-xs font-semibold text-text-secondary">
383	        {task.task_name}
384	      </span>
385	      <span
386	        className={
387	          "shrink-0 px-2 py-0.5 text-xs font-semibold uppercase tracking-wide " +
388	          statusStyle.bg +
389	          " " +
390	          statusStyle.text
391	        }
392	      >
393	        {formatStatusLabel(task.status)}
394	      </span>
395	      <span className="min-w-0 truncate text-sm font-medium text-text-primary">
396	        {task.title || task.task_name}
397	      </span>
398	      {task.is_blocked && (
399	        <AlertCircle
400	          className="ml-auto h-3.5 w-3.5 shrink-0 text-danger"
401	          aria-hidden="true"
402	        />
403	      )}
404	    </button>
405	  );
406	}
407	
408	function FeatureDocumentPanel({
409	  feature,
410	  documentType,
411	}: {
412	  feature: FeatureDetail;
413	  documentType: string;
414	}) {
415	  const doc = (feature.documents ?? []).find(
416	    (d) => d.document_type === documentType,
417	  );
418	
419	  if (!doc) {
420	    return (
421	      <div
422	        data-feature-doc-empty={documentType}
423	        className="flex flex-1 flex-col items-center justify-center gap-2 py-20"
424	      >
425	        <p className="text-sm text-text-muted">
426	          {documentType === "product_spec"
427	            ? "No product spec available."
428	            : "No technical design available."}
429	        </p>
430	      </div>
431	    );
432	  }
433	
434	  return (
435	    <div
436	      data-feature-doc={documentType}
437	      className="mx-auto max-w-3xl px-6 py-6"
438	    >
439	      <div className="mb-4 flex items-center justify-between">
440	        <h2 className="text-sm font-semibold text-text-primary">
441	          {documentType === "product_spec" ? "Product Spec" : "Technical Design"}
442	        </h2>
443	        {doc.url && (
444	          <a
445	            href={doc.url}
446	            target="_blank"
447	            rel="noreferrer noopener"
448	            className="flex items-center gap-1.5 text-xs text-primary transition-colors hover:underline"
449	          >
450	            View source
451	            <ExternalLink className="h-3 w-3" aria-hidden="true" />
452	          </a>
453	        )}
454	      </div>
455	      <div className="border border-border bg-surface px-4 py-3 text-sm text-text-secondary">
456	        <p className="font-mono text-xs text-text-muted">{doc.source_path}</p>
457	      </div>
458	    </div>
459	  );
460	}
461	
462	function FeatureTaskDrilldown({
463	  workspaceId,
464	  featureId,
465	  taskId,
466	  onBack,
467	}: {
468	  workspaceId: string;
469	  featureId: string;
470	  taskId: string;
471	  onBack: () => void;
472	}) {
473	  const { task, loading, error, reload } = useFeatureTask(workspaceId, featureId, taskId);
474	
475	  if (loading) {
476	    return (
477	      <div
478	        data-feature-task-drilldown-loading
479	        className="flex flex-1 items-center justify-center"
480	      >
481	        <p className="text-sm text-text-muted">Loading task…</p>
482	      </div>
483	    );
484	  }
485	
486	  if (error) {
487	    return (
488	      <div
489	        data-feature-task-drilldown-error
490	        className="flex flex-1 flex-col items-center justify-center gap-4"
491	      >
492	        <AlertCircle className="h-8 w-8 text-danger" aria-hidden="true" />
493	        <p className="text-sm text-text-secondary">
494	          {error.message || "Failed to load task."}
495	        </p>
496	        <div className="flex gap-2">
497	          <button
498	            type="button"
499	            onClick={onBack}
500	            className="flex items-center gap-1.5 text-xs text-text-secondary transition-colors hover:text-text-primary"
501	          >
502	            <ArrowLeft className="h-3.5 w-3.5" aria-hidden="true" />
503	            Back to feature
504	          </button>
505	          {error.retryable && (
506	            <button
507	              type="button"
508	              onClick={reload}
509	              className="flex items-center gap-2 border border-border bg-surface px-3 py-1.5 text-xs font-medium text-text-primary transition-colors hover:bg-surface-subtle"
510	            >
511	              <RefreshCw className="h-3.5 w-3.5" aria-hidden="true" />
512	              Retry
513	            </button>
514	          )}
515	        </div>
516	      </div>
517	    );
518	  }
519	
520	  if (!task) return null;
521	
522	  return <DrilldownTaskContent task={task} onBack={onBack} onReload={reload} />;
523	}
524	
525	function DrilldownTaskContent({
526	  task,
527	  onBack,
528	  onReload,
529	}: {
530	  task: TaskDetail;
531	  onBack: () => void;
532	  onReload: () => void;
533	}) {
534	  const statusStyle = getStatusStyle(task.status);
535	
536	  return (
537	    <div
538	      data-feature-task-drilldown-content
539	      className="flex h-full flex-col overflow-hidden"
540	    >
541	      <header className="flex shrink-0 items-center gap-3 border-b border-border bg-surface px-6 py-4">
542	        <button
543	          type="button"
544	          data-back-to-feature
545	          onClick={onBack}
546	          aria-label="Back to feature"
547	          className="flex items-center gap-1.5 text-xs text-text-secondary transition-colors hover:text-text-primary"
548	        >
549	          <ArrowLeft className="h-3.5 w-3.5" aria-hidden="true" />
550	          Feature
551	        </button>
552	        <span className="h-4 w-px bg-border" aria-hidden="true" />
553	        <div className="flex min-w-0 flex-1 flex-wrap items-center gap-2">
554	          <span className="shrink-0 bg-chip-bg px-2 py-0.5 font-mono text-xs font-semibold text-text-secondary">
555	            {task.task_name}
556	          </span>
557	          <span
558	            className={
559	              "shrink-0 px-2 py-0.5 text-xs font-semibold uppercase tracking-wide " +
560	              statusStyle.bg +
561	              " " +
562	              statusStyle.text
563	            }
564	          >
565	            {formatStatusLabel(task.status)}
566	          </span>
567	          <h2 className="min-w-0 truncate text-base font-semibold text-text-primary">
568	            {task.title || task.task_name}
569	          </h2>
570	        </div>
571	        <button
572	          type="button"
573	          onClick={onReload}
574	          aria-label="Reload task"
575	          className="shrink-0 p-1 text-text-secondary transition-colors hover:text-text-primary"
576	        >
577	          <RefreshCw className="h-4 w-4" aria-hidden="true" />
578	        </button>
579	      </header>
580	
581	      <div className="flex-1 overflow-y-auto px-6 py-6">
582	        <div className="mx-auto max-w-3xl space-y-8">
583	          <DrilldownMetadataSection task={task} />
584	          {task.depends_on && task.depends_on.length > 0 && (
585	            <DrilldownDependenciesSection task={task} />
586	          )}
587	          {task.pr_refs && task.pr_refs.length > 0 && (
588	            <DrilldownPrRefsSection task={task} />
589	          )}
590	        </div>
591	      </div>
592	    </div>
593	  );
594	}
595	
596	function DrilldownMetadataSection({ task }: { task: TaskDetail }) {
597	  return (
598	    <section>
599	      <div className="grid grid-cols-2 gap-x-8 gap-y-5">
600	        <div className="flex flex-col gap-1.5">
601	          <span className="text-xs font-medium uppercase tracking-wide text-text-secondary">
602	            Repository
603	          </span>
604	          {task.repo ? (
605	            <a
606	              href={`https://github.com/${task.repo}`}
607	              target="_blank"
608	              rel="noreferrer noopener"
609	              className="inline-flex items-center gap-1.5 text-sm text-primary transition-colors hover:underline"
610	            >
611	              {task.repo}
612	              <ExternalLink className="h-3.5 w-3.5" aria-hidden="true" />
613	            </a>
614	          ) : (
615	            <span className="text-sm italic text-text-muted">None</span>
616	          )}
617	        </div>
618	        <div className="flex flex-col gap-1.5">
619	          <span className="text-xs font-medium uppercase tracking-wide text-text-secondary">
620	            Branch
621	          </span>
622	          {task.branch ? (
623	            <span className="font-mono text-xs text-success">{task.branch}</span>
624	          ) : (
625	            <span className="text-sm italic text-text-muted">None</span>
626	          )}
627	        </div>
628	        {task.blocked_reason && (
629	          <div className="col-span-2 flex flex-col gap-1.5">
630	            <span className="text-xs font-medium uppercase tracking-wide text-text-secondary">
631	              Blocked Reason
632	            </span>
633	            <div
634	              data-drilldown-blocked-reason
635	              className="flex items-start gap-2 border border-danger bg-danger-bg px-3 py-2"
636	            >
637	              <AlertCircle
638	                className="mt-0.5 h-4 w-4 shrink-0 text-danger"
639	                aria-hidden="true"
640	              />
641	              <span className="text-sm text-danger">{task.blocked_reason}</span>
642	            </div>
643	          </div>
644	        )}
645	      </div>
646	    </section>
647	  );
648	}
649	
650	function DrilldownDependenciesSection({ task }: { task: TaskDetail }) {
651	  return (
652	    <section>
653	      <h2 className="mb-4 text-xs font-semibold uppercase tracking-widest text-text-muted">
654	        Dependencies
655	      </h2>
656	      <div className="flex flex-wrap gap-2">
657	        {task.depends_on.map((dep) => (
658	          <span
659	            key={dep}
